require_once __DIR__ . '/../../../config.php'; require_once __DIR__ . '/../../../db.php'; require_once __DIR__ . '/../../../includes/tie/bootstrap.php'; require_once __DIR__ . '/../../../includes/tie/Api.php';
$requestId = UthengaTieObservability::requestId();
try { if ($_SERVER['REQUEST_METHOD'] !== 'POST') throw UthengaTieErrors::validation(['method' => 'POST is required.']); foreach (['booking', 'plans', 'query', 'availability'] as $feature) UthengaTieApi::requireFeature($feature); $user = UthengaTieApi::requireAuthenticatedUser(); UthengaTieApi::requireCsrf(); UthengaTieApi::requireRateLimit('booking', UthengaTieConfig::integer('TIE_BOOKING_RATE_LIMIT', 5), 60, $requestId); $request = UthengaTieBookingContracts::request(UthengaTieApi::input()); $started = microtime(true); $kernel = new UthengaTieKernel(); if (session_status() === PHP_SESSION_ACTIVE) session_write_close(); $result = $kernel->booking->execute($request, $user['id'])->toArray(); $duration = round((microtime(true) - $started) * 1000, 2); UthengaTieObservability::log('booking.executed', $requestId, ['module' => 'booking', 'feature' => 'orchestration', 'status' => strtolower($result['status']), 'duration_ms' => $duration]); UthengaTieMetrics::record('booking_execution_latency_ms', $duration, $requestId, ['module' => 'booking', 'feature' => 'orchestration', 'status' => strtolower($result['status'])]); UthengaTieApi::respond(['success' => true, 'request_id' => $requestId, 'booking' => $result]); } catch (Throwable $error) { UthengaTieApi::handleError($error, $requestId); }
